---@class ActivityOpenLatticeTaskDialog
---@field Env                           	ActivityOpenLatticeTaskDialog
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field AllDrawRewardsBtn             	UnityEngine.UI.Button
---@field BtnClose                      	UnityEngine.RectTransform
---@field TaskListView                  	SuperScrollView.LoopListView2
local ActivityOpenLatticeTaskDialog = Class("ActivityOpenLatticeTaskDialog")
ActivityOpenLatticeTaskDialog.CloseEvent = "ActivityOpenLatticeTaskDialogCloseEvent"

function ActivityOpenLatticeTaskDialog:__init()
    self.taskList = {}
    self.isDrawing = false
end

function ActivityOpenLatticeTaskDialog:__delete()
    self.taskList = nil
    self.controller = nil
end

function ActivityOpenLatticeTaskDialog:Awake()
    SetButtonAction(self.BtnClose.gameObject, function()
        UIModule.BackDialog()
    end)

    SetButtonAction(self.AllDrawRewardsBtn.gameObject,Bind(self,self.OnBtnAllDrawRewardClick))
end

function ActivityOpenLatticeTaskDialog:OnFocus(focus)
    printInfo("--->> focus", focus)
end

function ActivityOpenLatticeTaskDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.parameters = self.controller.Argument.parameters
        if self.parameters == nil or self.parameters.activityUuid == nil then
            self.parameters = {}
            self.parameters.activityUuid = ActivityMgr:GetActivityIdByActivityType(ActivityConstants.ActivityType.OpenGrid)
        end
        local activityData = self:GetDojoByActivityId(self.parameters.activityUuid)
        local data = CfUtils.GetCfVo(AutoIds.IdSetting6128, "OpenGridActivityVo", activityData.activityContentId or 1)
        local goodIds = string.split(data.itemId,";")
        CfUtils.RefreshTopGoods(goodIds)
        GameUtils.Request(
                Interfaces.ActivityOpenGridTask,
                {activityUuid = self.parameters.activityUuid},
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        print("---->>"..table.dump(response.data, nil, 3))
                        self.taskList = response.data.tasks
                        self:FreshList()
                    end
                end
        )
    end))
    return coWait
end


---@private
function ActivityOpenLatticeTaskDialog:GetDojoByActivityId(activityId)
    local activties = ActivityMgr:GetActivityComponent():GetActivityData()
    for i, v in pairs(activties) do
        if checkInt(v.id) == activityId then
            return v
        end
    end
end

function ActivityOpenLatticeTaskDialog:FreshList()
    self:SortTaskData()
    if not self.TaskListView.IsListViewInit then
        self.TaskListView:InitListView(#self.taskList, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.TaskListView, #self.taskList)
    end
end

function ActivityOpenLatticeTaskDialog:SortTaskData()
    local canList = {}
    local notList = {}
    local getList = {}
    for k, v in pairs(self.taskList) do
        if v.status == Constants.GetStatus.Can then
            table.insert(canList, v)
        elseif v.status == Constants.GetStatus.Not then
            table.insert(notList, v)
        elseif v.status == Constants.GetStatus.Has then
            table.insert(getList, v)
        end
    end
    self.taskList = {}
    for k, v in pairs(canList) do
        table.insert(self.taskList, v)
    end
    for k, v in pairs(notList) do
        table.insert(self.taskList, v)
    end
    for k, v in pairs(getList) do
        table.insert(self.taskList, v)
    end
end

function ActivityOpenLatticeTaskDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local luaIndex = index + 1
    local cell = listView:NewListViewItem("Cell")
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, "Game.Activity.OpenGrid.ActivityOpenGridTaskPopupCell")
    if nodeEnv then
        local data = self.taskList[luaIndex]
        nodeEnv:FreshBaseUI(data)
        nodeEnv:SetBtnCallBack(function()
            GameUtils.Request(
                    Interfaces.ActivityOpenGridTaskGetReward,
                    {activityUuid = self.parameters.activityUuid, taskId = data.id},
                    function(request, response)
                        if checkInt(response.errCode) == 0 then
                            print("---->>"..table.dump(response.data, nil, 3))
                            self.taskList[luaIndex].status = Constants.GetStatus.Has
                            GoodsUtils.DrawRewards(response.data.rewards,true)
                            UIModule.OpenDialog(
                                    {
                                        id = Constants.UITypeIds.UICommonRewardPop,
                                        parameters = { rewards = response.data.rewards, cb = function()
                                        end }
                                    }
                            )
                            self:FreshList()
                        end
                    end
            )
        end)
    end
    return cell
end

function ActivityOpenLatticeTaskDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local hasUnclaimed = false
        for i, v in pairs(self.taskList) do
            if checkNumber(v.status) == Constants.GetStatus.Can then
                hasUnclaimed = true
                break
            end
        end
        Events.Broadcast(ActivityOpenLatticeTaskDialog.CloseEvent, hasUnclaimed)
    
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function ActivityOpenLatticeTaskDialog:OnBtnAllDrawRewardClick()
    local isHaveDraw = false
    local ladderTaskList = checkTable(self.taskList)
    for _, listData in ipairs(ladderTaskList) do
        if checkInt(listData.status) == Constants.GetStatus.Can then
            isHaveDraw = true
            break
        end
    end
    if not isHaveDraw then
        GameUtils.Toast(localize("暂无奖励可领取"))
        return
    end
    self:DrawRewards()
end

function ActivityOpenLatticeTaskDialog:DrawRewards()
    if self.isDrawing then
        return
    end
    self.isDrawing = true
    GameUtils.Request(
            Interfaces.ActivityOpenGridTaskDrawAll,
            {activityUuid = self.parameters.activityUuid},
            function(request, response)
                if checkInt(response.errCode) == 0 then
                    print("---->>"..table.dump(response.data, nil, 3))
                    self:RefreshTaskStatus()
                    GoodsUtils.DrawRewards(response.data.rewards,true)
                    UIModule.OpenDialog(
                            {
                                id = Constants.UITypeIds.UICommonRewardPop,
                                parameters = { rewards = response.data.rewards, cb = function()
                                end }
                            }
                    )
                    self:FreshList()
                end
                self.isDrawing = false
            end
    )
end

function ActivityOpenLatticeTaskDialog:RefreshTaskStatus()
    local ladderTaskList = checkTable(self.taskList)
    for _, listData in ipairs(ladderTaskList) do
        if checkInt(listData.status) == Constants.GetStatus.Can then
            listData.status = Constants.GetStatus.Has
        end
    end
end

return ActivityOpenLatticeTaskDialog